const BASE = "https://api.lokalise.com/api2";
const PID = "31393214664f295f94dd86.76792605";
const TOTAL = 17522, LIMIT = 200;
const out = [];
for (let p = 1; p <= Math.ceil(TOTAL / LIMIT); p++) {
  out.push({ json: { page: p, url: BASE + "/projects/" + PID + "/keys?limit=" + LIMIT + "&page=" + p
    + "&include_translations=1&filter_translation_lang_ids=640,673" } });
}
return out;

const MT = 29251;
const snapshot = [];
const keys = [];
const errors = [];
let seen = 0;
for (const it of $input.all()) {
  const r = it.json || {};
  const b = r.body !== undefined ? r.body : r;
  if (!Array.isArray(b.keys)) { errors.push({ status: r.statusCode }); continue; }
  for (const k of b.keys) {
    seen++;
    for (const t of (k.translations || [])) {
      if (t.language_iso !== 'fr') continue;
      if (!t.translation || !String(t.translation).trim()) continue;
      const st = (t.custom_translation_statuses || []).map(s => s.status_id);
      if (st.indexOf(MT) === -1) continue;
      snapshot.push({ key_id: k.key_id, key_name: (k.key_name && k.key_name.web) || '',
        language_iso: 'fr', translation_id: t.translation_id,
        previous_translation: t.translation,
        previous_is_reviewed: t.is_reviewed, previous_is_fuzzy: t.is_fuzzy,
        previous_custom_translation_status_ids: st,
        modified_by_email: t.modified_by_email || null });
      keys.push({ key_id: k.key_id, translations: [{ language_iso: 'fr', translation: '',
        is_reviewed: false, is_fuzzy: false, custom_translation_status_ids: [] }] });
    }
  }
}
return [{ json: {
  keys_seen: seen, errors: errors, to_revert: snapshot.length,
  snapshot: snapshot,
  url: 'https://api.lokalise.com/api2/projects/31393214664f295f94dd86.76792605/keys',
  payload: { keys: keys }
} }];

const r = $input.first().json || {};
const b = r.body !== undefined ? r.body : r;
const s = $('Snapshot and build revert').first().json;
const keys = Array.isArray(b.keys) ? b.keys : [];
let cleared = 0, stillFilled = 0;
for (const k of keys) {
  for (const t of (k.translations || [])) {
    if (t.language_iso !== 'fr') continue;
    if (t.translation && String(t.translation).trim()) stillFilled++; else cleared++;
  }
}
return [{ json: {
  keys_scanned: s.keys_seen, fetch_errors: s.errors,
  requested_clear: s.to_revert, lokaliseStatus: r.statusCode,
  keys_returned: keys.length, cleared_confirmed: cleared, still_filled: stillFilled,
  errors: Array.isArray(b.errors) ? b.errors : [],
  rawError: keys.length ? null : JSON.stringify(b).slice(0, 400),
  snapshot: s.snapshot
} }];
